/*
 * WebAssembly-facing wrapper around the acados solver generated by ocp.py.
 *
 * One solver instance per module. Plain scalar arguments and returns only,
 * so JS calls the exports directly without marshalling arrays into wasm
 * memory. Coordinates and units are the sim's (see ocp.py).
 *
 *   mpc_init()                          create the solver; 0 on success
 *   mpc_reset()                         forget the previous solution
 *   mpc_set_reference(x, y, throttle)   where to go, and the input to rest at
 *   mpc_set_floor(k, floor)             max plane y for the centre at stage k
 *   mpc_solve(x, y, vx, vy, th, om, n)  n real-time iterations from this state;
 *                                       returns the acados status
 *   mpc_u(i), mpc_x(k, i)               first input, predicted states
 *   mpc_horizon(), mpc_stage_dt()       N and the shooting interval [s]
 *   mpc_solve_time()                    time spent in the last mpc_solve [s]
 */
#include "acados_c/ocp_nlp_interface.h"
#include "acados_solver_lander.h"

#define NX LANDER_NX
#define NU LANDER_NU
#define N LANDER_N

static lander_solver_capsule *capsule;
static ocp_nlp_config *config;
static ocp_nlp_dims *dims;
static ocp_nlp_in *in;
static ocp_nlp_out *out;
static ocp_nlp_solver *solver;

static double rest_input[NU];
static int fresh = 1; /* next solve has no previous solution to start from */
static double last_solve_time;

int mpc_init(void) {
    capsule = lander_acados_create_capsule();
    int status = lander_acados_create(capsule);
    if (status) return status;
    config = lander_acados_get_nlp_config(capsule);
    dims = lander_acados_get_nlp_dims(capsule);
    in = lander_acados_get_nlp_in(capsule);
    out = lander_acados_get_nlp_out(capsule);
    solver = lander_acados_get_nlp_solver(capsule);
    return 0;
}

void mpc_reset(void) {
    /* Zero the iterates and the QP solver's memory; references, floors and
       options stay (they're set before every solve anyway). */
    lander_acados_reset(capsule, 1, 0, 0, 0);
    fresh = 1;
}

void mpc_set_reference(double x, double y, double throttle) {
    double yref[NX + NU] = {x, y, 0, 0, 0, 0, throttle, 0};
    for (int k = 0; k < N; k++) ocp_nlp_cost_model_set(config, dims, in, k, "yref", yref);
    ocp_nlp_cost_model_set(config, dims, in, N, "yref", yref); /* terminal: first NX */
    rest_input[0] = throttle;
    rest_input[1] = 0;
}

void mpc_set_floor(int k, double floor) {
    lander_acados_update_params(capsule, k, &floor, 1);
}

int mpc_solve(double x, double y, double vx, double vy, double th, double om, int iterations) {
    double x0[NX] = {x, y, vx, vy, th, om};
    ocp_nlp_constraints_model_set(config, dims, in, out, 0, "lbx", x0);
    ocp_nlp_constraints_model_set(config, dims, in, out, 0, "ubx", x0);
    if (fresh) {
        /* No previous solution: start from staying put at the resting input. */
        for (int k = 0; k <= N; k++) ocp_nlp_out_set(config, dims, out, in, k, "x", x0);
        for (int k = 0; k < N; k++) ocp_nlp_out_set(config, dims, out, in, k, "u", rest_input);
        fresh = 0;
    }
    int status = 0;
    double total = 0;
    for (int i = 0; i < iterations; i++) {
        status = lander_acados_solve(capsule);
        double t = 0;
        ocp_nlp_get(solver, "time_tot", &t);
        total += t;
    }
    last_solve_time = total;
    return status;
}

double mpc_u(int i) {
    double u[NU];
    ocp_nlp_out_get(config, dims, out, 0, "u", u);
    return u[i];
}

double mpc_x(int k, int i) {
    double xk[NX];
    ocp_nlp_out_get(config, dims, out, k, "x", xk);
    return xk[i];
}

int mpc_horizon(void) { return N; }

double mpc_stage_dt(void) { return in->Ts[0]; }

double mpc_solve_time(void) { return last_solve_time; }
